import unittest

import api
from users import UserService


class UserEndpointTest(unittest.TestCase):
    def test_suspend_user(self):
        service = UserService({"u1": {"id": "u1", "status": "active"}})
        result = api.suspend_user("u1", service)
        self.assertEqual("suspended", result["status"])


if __name__ == "__main__":
    unittest.main()
